// === Tab: ParticleJam ===
var particles = [];

function setup() {
  createCanvas(1112, 834);
  background(51);  
  colorMode(HSB, 255);

  for(var i = 0; i < 25; i++){
  	particles[i] = new Particle();
  }
} 

function draw() {

  for(var i = 0; i < particles.length; i++){
    particles[i].update();
    particles[i].show();
  }
}

function mousePressed(){
  save('pix.jpg');
}


// === Tab: Particle ===
function Particle() {

  this.pos = createVector(random(width), random(height));
  this.vel = createVector(random(5) + 1, random(5) + 1);
  this.r = 1;
  this.rcount = 0;
  this.rthresh = random(300) + 50;
  this.phase = 0;
  this.maxr = random(400) + 20;

  this.dice = random(1);
  if(this.dice < 0.5){
  	this.vel.x = this.vel.x * -1;
  } 
  this.dice = random(1);
  if(this.dice < 0.5){
  	this.vel.y = this.vel.y * -1;
  }

  this.current = color(random(255), 255, random(150, 255));
  this.next = color(random(255), 255, random(150, 255));
  this.lerped = color(random(255), 255, random(150, 255));
  this.counter = 0;

  this.update = function() {

    if(this.pos.x < 0 || this.pos.x > width){
      this.vel.x = this.vel.x * -1;
    }

    if(this.pos.y < 0 || this.pos.y > height){
      this.vel.y = this.vel.y * -1;
    }

    this.pos = this.pos.add(this.vel);
  }

  this.show = function() {
	noStroke();

    if(this.counter > 1){
      this.counter = 0;
      this.current = this.next;
      this.next = color(random(255), 255, random(150, 255));
    }

    this.lerped = lerpColor(this.current, this.next, this.counter);
    this.counter += 0.01;
    stroke(this.lerped);
    noFill();

    if(this.rcount > this.rthresh){
    	this.rcount = 0;
    }
    this.phase = this.rcount / this.rthresh;
   	this.r = sin(this.phase * TWO_PI) * this.maxr;   

    this.rcount += 1;

    ellipse(this.pos.x, this.pos.y, this.r, this.r);
  }
}

